sp_widget.client_script:
function($scope, $rootScope, $timeout) {
    var chartDCL = null;

    $scope.anoSelecionadoDCL = ""; 
    $scope.exibirGraficoDCL = false;

    var coresDCL = {
        apurado: '#a7b9e8', // Realizado
        meta: '#4b77bf'     // Meta
    };

    // --- 1. OUVINTE DO EVENTO ---
    $rootScope.$on('anoSelecionado', function(event, ano) {
        $scope.anoSelecionadoDCL = ano;
        carregarDadosDCLFiltrado(); 
    });

    function carregarDadosDCLFiltrado() {
        var filtros = {
            ano: $scope.anoSelecionadoDCL 
        };

        $scope.server.get(filtros).then(function(response) {
            var dados = response.data.dadosGraficoDCL || [];

            $timeout(function() {
                montarGraficoDCL(dados);
            });
        });
    }

    carregarDadosDCLFiltrado();

    function montarGraficoDCL(listaDados) {

        // 1. Prepara os dados (igual antes)
        var anosPresentes = [];
        listaDados.forEach(function(item) {
            if (anosPresentes.indexOf(item.ano) === -1) {
                anosPresentes.push(item.ano);
            }
        });

        anosPresentes.sort(function(a, b) {
            return parseInt(a) - parseInt(b);
        });

        // Se não tiver dados, destrói para limpar a tela e sai
        if (anosPresentes.length === 0) {
            if (chartDCL) {
                chartDCL.destroy();
                chartDCL = null;
            }
            $scope.exibirGraficoDCL = false;
            return;
        }

        $scope.exibirGraficoDCL = true;

        function parseValue(val) {
            if (!val) return null;
            var cleanVal = val.toString().replace(',', '.');
            return parseFloat(cleanVal);
        }

        var dadosApurado = anosPresentes.map(function(ano) {
            var item = listaDados.find(function(d) { return d.ano === ano; });
            return item ? parseValue(item.apurado) : null;
        });
        var dadosMeta = anosPresentes.map(function(ano) {
            var item = listaDados.find(function(d) { return d.ano === ano; });
            return item ? parseValue(item.meta) : null;
        });

        // 2. Cálculo de Escalas (Max/Min)
        var todosValores = dadosApurado.concat(dadosMeta).filter(function(v) {
            return v !== null && !isNaN(v);
        });

        var maxVal = todosValores.length > 0 ? Math.max.apply(null, todosValores) : 100;
        var minVal = todosValores.length > 0 ? Math.min.apply(null, todosValores) : 0;
        var PADDING_FIXO = (maxVal - minVal) * 0.1; 
        if (PADDING_FIXO === 0) PADDING_FIXO = 5;
        var scaleMax = maxVal + PADDING_FIXO;
        var scaleMin = minVal >= 0 ? 0 : minVal - PADDING_FIXO;

        // --- LÓGICA DE UPDATE SUAVE ---

        if (chartDCL) {
            // SE O GRÁFICO JÁ EXISTE: Apenas atualizamos os dados e escalas
            chartDCL.data.labels = anosPresentes;
            chartDCL.data.datasets[0].data = dadosApurado;
            chartDCL.data.datasets[1].data = dadosMeta;

            // Atualiza escalas dinamicamente
            chartDCL.options.scales.y.min = scaleMin;
            chartDCL.options.scales.y.max = scaleMax;

            chartDCL.update(); // <--- MÁGICA ACONTECE AQUI (Animação)

        } else {
            // SE O GRÁFICO NÃO EXISTE: Criamos do zero (apenas na primeira vez)
            var ctx = document.getElementById('graficoResultadoDCL').getContext('2d');

            var datasets = [{
                label: 'Realizado',
                data: dadosApurado,
                backgroundColor: coresDCL.apurado,
                borderColor: coresDCL.apurado,
                borderWidth: 1,
                pointStyle: 'rect',
                pointBackgroundColor: coresDCL.apurado,
                pointBorderColor: coresDCL.apurado,
                pointBorderWidth: 0
            },{
                label: 'Meta',
                data: dadosMeta,
                backgroundColor: coresDCL.meta,
                borderColor: coresDCL.meta,
                borderWidth: 1,
                pointStyle: 'rect',
                pointBackgroundColor: coresDCL.meta,
                pointBorderColor: coresDCL.meta,
                pointBorderWidth: 0
            }];

            chartDCL = new Chart(ctx, {
                type: 'bar',
                data: {
                    labels: anosPresentes,
                    datasets: datasets
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    animation: {
                        duration: 750, // Duração da animação
                        easing: 'easeInOutQuart' // Tipo de suavização
                    },
                    scales: {
                        x: {
                            display: true,
                            offset: true,
                            grid: { offset: true },
                            ticks: {
                                color: '#0E2B69',
                                font: {
                                    size: 16,
                                    weight: 800,
                                    family: 'Roboto Flex, sans-serif',
                                }
                            }
                        },
                        y: {
                            display: true,
                            position: 'left',
                            min: scaleMin,
                            max: scaleMax,
                            ticks: {
                                callback: function(value) {
                                    return value.toLocaleString('pt-BR', {
                                        minimumFractionDigits: 2,
                                        maximumFractionDigits: 2
                                    }) + '%';
                                },
                                color: '#0E2B69',
                                font: {
                                    size: 14,
                                    family: 'Roboto Flex, sans-serif'
                                }
                            }
                        }
                    },
                    plugins: {
                        legend: {
                            display: true,
                            position: 'top',
                            labels: { usePointStyle: true }
                        },
                        tooltip: {
                            enabled: true,
                            callbacks: {
                                label: function(context) {
                                    var raw = context.raw || 0;
                                    return context.dataset.label + ': ' +
                                        raw.toLocaleString('pt-BR', {
                                            minimumFractionDigits: 2,
                                            maximumFractionDigits: 2
                                        }) + '%';
                                }
                            }
                        },
                        datalabels: {
                            anchor: 'end',
                            align: function(context) {
                                return context.raw < 0 ? 'bottom' : 'top';
                            },
                            formatter: function(value) {
                                if (value === null) return '';
                                return value.toLocaleString('pt-BR', {
                                    minimumFractionDigits: 2,
                                    maximumFractionDigits: 2
                                }) + '%';
                            },
                            color: '#000',
                            font: { weight: 'bold' }
                        }
                    }
                }
            });
        }
    }
}

sp_widget.css:
canvas {
  display: block;
  margin: 0 auto;
}

h3, div, span {
 font-family: 'Roboto Flex', sans-serif;
}

.titleEnd{
   font-family: Roboto;
  font-weight: 500;
  font-style: Medium;
  font-size: 24px;
  leading-trim: NONE;
  line-height: 100%;
  letter-spacing: 0%;
	color:#021770;
}

/* --- Media Queries para Responsividade --- */

/* Telas Pequenas (Mobile S, M, L - até 767px) */
@media (max-width: 767px) {
  canvas {
    max-width: 90%; /* Ajustar a largura máxima do canvas */
  }
  h3 {
    font-size: 1rem; /* Ajustar o tamanho da fonte do título */
  }
}

/* Tablets (iPad Mini, iPad Air, Surface Duo, Galaxy Z Fold 5 - 768px até 1023px) */
@media (min-width: 768px) and (max-width: 1023px) {
  canvas {
    max-width: 80%;
  }
  h3 {
    font-size: 1.1rem;
  }
}

/* Laptops e Telas Maiores (iPad Pro, Surface Pro 7, Laptops, 4K - 1024px em diante) */
@media (min-width: 1024px) {
  canvas {
    max-width: none;
  }
  h3 {
  }
}

/* Ajustes para o Surface Duo (540x720) */
@media (width: 540px) and (height: 720px) {
    canvas {
        max-width: 95%;
    }
}

/* Ajustes para Galaxy Z Fold 5 (max-width: 350px) */
@media (max-width: 350px) {
    h3 {
        font-size: 0.9rem;
    }
}

sp_widget.script:
(function() {
    input = input || {};
    // Variável única de saída para evitar conflito no data object
    data.dadosGraficoDCL = [];

    // Pega o ano enviado pelo Client Script
    var anoFiltro = input.ano || "";

    var grDCL = new GlideRecord('x_sded9_portal_t_0_limite_de_endividamento');
    // Mantém o filtro de DCL que você já tinha configurado
    grDCL.addQuery('indicador_de_endividamento_publico', 'dcl');

    if (anoFiltro && anoFiltro !== "") {
        grDCL.addQuery('u_ano', anoFiltro);
    }

    grDCL.orderBy('u_ano');
    grDCL.query();

    var listaDCL = [];
    while (grDCL.next()) {
        listaDCL.push({
            ano: grDCL.getValue('u_ano').toString(),
            apurado: grDCL.getValue('u_realizado') || '0',
            meta: grDCL.getValue('u_meta') || '0'
        });
    }

    data.dadosGraficoDCL = listaDCL;
})();
